package replica;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.Drawable;import android.view.View;
/** SystemUI optical model: original sampled mode or transparent overlay above live window blur. */
public final class OriginalMaterial extends Drawable {
 private static String source,liveSource;private final boolean live;private final int kind;private final Paint paint=new Paint(3);private final LightSurface fallback;private RuntimeShader shader;private BitmapShader input;private Bitmap frame;private final float radius,density;private boolean dark,blur,stroke,managed;private final int[] screen=new int[2];private final Matrix map=new Matrix();private boolean failed,drawLogged;
 private boolean opaqueFallback;
 private final Context context;private final MaterialThemeBinding theme;
 public OriginalMaterial(Context c){this(c,22,0,false);}
 public OriginalMaterial(Context c,float corner,int style,boolean realtime){context=c;live=realtime;kind=style;dark=ColorOsTheme.dark(c);blur=ColorOsTheme.materialBlur(c);stroke=ColorOsTheme.materialStroke(c);radius=PanelStyle.dp(c,corner);density=c.getResources().getDisplayMetrics().density;fallback=new LightSurface(c,corner,style);fallback.managedByParent();theme=new MaterialThemeBinding(this,this::refreshTheme,this::releaseSample);frame=blur?MaterialBackdrop.frames.get(c):null;try{if((live?liveSource:source)==null){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(java.io.InputStream in=c.getAssets().open(live?"coloros-live-optics.agsl":"coloros-qs-material.agsl")){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);}if(live)liveSource=bytes.toString("UTF-8");else source=bytes.toString("UTF-8");}shader=new RuntimeShader(live?liveSource:source);if(!live&&frame!=null)bindSample();uniform("uMatrix",1,0,0,0,1,0,0,0,1);uniform("uMatrixParams",1,1,0,0);shader.setIntUniform("uEnableBlend",0);shader.setIntUniform("uEnableMetaBall",0);// Test19 optical baseline; quick-panel contrast is composed separately.
float[] tint=new float[20];tint[1]=1;tint[2]=tint[3]=tint[4]=89f/255f;tint[5]=kind==2?77f/255f:0f;
if(kind==3){tint[2]=tint[3]=tint[4]=dark?.12f:.84f;tint[5]=.78f;}
uniform("u_colorArray",tint);uniform("u_edgeReferenceAspect",kind==2||kind==3?60f/140f:0f);android.util.Log.i("ReplicaMaterial",live?"live optical overlay ready":"original AGSL ready");}catch(Exception e){failed=true;android.util.Log.e("ReplicaMaterial","AGSL setup failed",e);}}
 private void uniform(String name,float... values){shader.setFloatUniform(name,values);}
 @Override protected void onBoundsChange(Rect b){fallback.setBounds(b);if(failed)return;try{float w=b.width(),h=b.height(),shortSide=Math.min(w,h),s=density/3.5f,corner=Math.min(radius,shortSide/2),weight=Math.abs(w-h)<3?1:2;uniform("u_commonArray",w/2,h/2,w/2,h/2,w/2,h/2,corner,weight);uniform("u_size",w,h);uniform("u_corner",corner);uniform("u_weight",weight);uniform("u_faceLight",kind==2&&stroke?.05f:0f);uniform("u_edgeArray",1,1,1,1.6f*s,3f*s,1.6f*s,3f*s,stroke?(dark?.35f:.25f):0,stroke?(dark?.4f:.6f):0,.25f,.6f,.15f,.5f,0,10,.5f);uniform("u_shadowArray",1,1,1,stroke?(dark?.07f:.15f):0,0,0,40*s,0,36*s,1.3f,1.3f,20,.5f,6*s,20,.3f);}catch(Exception e){failed=true;android.util.Log.e("ReplicaMaterial","Uniform setup failed",e);}}
 void useOpaqueFallback(){opaqueFallback=true;fallback.useOpaqueBase();}
 void managedByParent(){managed=true;}
 private void bindSample(){input=new BitmapShader(frame,Shader.TileMode.CLAMP,Shader.TileMode.CLAMP);input.setFilterMode(BitmapShader.FILTER_MODE_LINEAR);shader.setInputShader("uniBDFBitmap",input);}
 void releaseSample(){frame=null;input=null;paint.setShader(null);if(!live&&shader!=null)shader.setInputShader("uniBDFBitmap",new LinearGradient(0,0,1,1,Color.TRANSPARENT,Color.TRANSPARENT,Shader.TileMode.CLAMP));}
 void refreshTheme(){fallback.refreshTheme();themeChanged();invalidateSelf();}
 void themeChanged(){boolean nextDark=ColorOsTheme.dark(context),nextBlur=ColorOsTheme.materialBlur(context),nextStroke=ColorOsTheme.materialStroke(context);boolean changed=dark!=nextDark||blur!=nextBlur||stroke!=nextStroke;dark=nextDark;blur=nextBlur;stroke=nextStroke;fallback.themeChanged();if(!changed)return;if(!blur){releaseSample();MaterialBackdrop.release(context);}if(!failed){float[] tint=new float[20];tint[1]=1;tint[2]=tint[3]=tint[4]=89f/255f;tint[5]=kind==2?77f/255f:0f;if(kind==3){tint[2]=tint[3]=tint[4]=dark?.12f:.84f;tint[5]=.78f;}uniform("u_colorArray",tint);onBoundsChange(getBounds());}invalidateSelf();}
 @Override public void draw(Canvas c){if(!managed)theme.track();themeChanged();if(!live&&blur&&frame==null){frame=MaterialBackdrop.frames.get(context);if(frame!=null&&!failed)bindSample();}if(opaqueFallback||!blur||failed||(!live&&frame==null)||!c.isHardwareAccelerated()){fallback.draw(c);return;}try{Drawable.Callback callback=getCallback();while(callback instanceof Drawable)callback=((Drawable)callback).getCallback();if(callback instanceof View)((View)callback).getLocationOnScreen(screen);if(!live){map.reset();map.setScale(4,4);map.postTranslate(-screen[0],-screen[1]);input.setLocalMatrix(map);shader.setInputShader("uniBDFBitmap",input);}paint.setShader(shader);c.drawRect(getBounds(),paint);if(!drawLogged){drawLogged=true;android.util.Log.i("ReplicaMaterial","GPU draw "+getBounds()+" screen="+screen[0]+","+screen[1]);}}catch(Exception e){failed=true;android.util.Log.e("ReplicaMaterial","AGSL draw failed",e);fallback.draw(c);}}
 @Override public void setAlpha(int a){paint.setAlpha(a);fallback.setAlpha(a);invalidateSelf();}@Override public void setColorFilter(ColorFilter f){paint.setColorFilter(f);fallback.setColorFilter(f);invalidateSelf();}@Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}@Override public void getOutline(Outline o){o.setRoundRect(getBounds(),radius);}
}
